---
import '../styles/global.css';
const { title, description } = Astro.props;

const colorId = import.meta.env.PUBLIC_COLORID || 'ocean';
const fontId = import.meta.env.PUBLIC_FONTID || 'dm-sans';
const radiusId = import.meta.env.PUBLIC_RADIUS || 'rounded';

const COLOR_MAP = {
  ocean:    [[217,91,35],  [158,64,42],  [15,92,62],   [210,40,98],  [222,47,11]],
  forest:   [[152,68,28],  [45,93,47],   [350,80,55],  [140,20,97],  [150,40,10]],
  midnight: [[235,70,42],  [170,60,45],  [25,95,58],   [230,25,97],  [235,50,12]],
  ruby:     [[350,72,42],  [25,90,55],   [200,75,45],  [350,20,97],  [350,45,12]],
  slate:    [[215,25,35],  [160,55,42],  [25,88,58],   [215,15,97],  [215,30,12]],
  coral:    [[16,80,50],   [195,65,42],  [280,55,55],  [16,30,97],   [16,50,12]],
  teal:     [[175,65,38],  [280,55,48],  [35,90,55],   [175,25,97],  [175,45,11]],
  plum:     [[270,55,40],  [150,55,42],  [20,88,58],   [270,15,97],  [270,40,12]],
};
const FONT_MAP = {
  'dm-sans':       { import: 'DM+Sans:opsz,wght@9..40,400;9..40,600;9..40,700', family: '"DM Sans", system-ui, sans-serif' },
  'plus-jakarta':  { import: 'Plus+Jakarta+Sans:wght@400;600;700;800',           family: '"Plus Jakarta Sans", system-ui, sans-serif' },
  'outfit':        { import: 'Outfit:wght@400;500;600;700',                       family: '"Outfit", system-ui, sans-serif' },
  'inter':         { import: 'Inter:wght@400;500;600;700',                        family: '"Inter", system-ui, sans-serif' },
};
const RADIUS_MAP = { sharp:'0rem', subtle:'0.375rem', rounded:'0.75rem', pill:'1.5rem' };
const pal  = COLOR_MAP[colorId]  || COLOR_MAP['ocean'];
const font = FONT_MAP[fontId]    || FONT_MAP['dm-sans'];
const rad  = RADIUS_MAP[radiusId] || '0.75rem';
const hsl  = (h, s, l) => h + ' ' + s + '% ' + l + '%';
const cssVars = '--primary:' + hsl(...pal[0]) + ';--secondary:' + hsl(...pal[1]) + ';--accent:' + hsl(...pal[2]) + ';--background:' + hsl(...pal[3]) + ';--foreground:' + hsl(...pal[4]) + ';--radius:' + rad + ';';
---
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>{title}</title>
  <meta name="description" content={description} />
  <meta property="og:title" content={title} />
  <meta property="og:description" content={description} />
  <meta property="og:image" content="https://images.pexels.com/photos/259027/pexels-photo-259027.jpeg?auto=compress&cs=tinysrgb&w=1200" />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href={`https://fonts.googleapis.com/css2?family=${font.import}&display=swap`} rel="stylesheet" media="print" onload="this.media='all'" />
  <style is:inline set:html={`:root { ${cssVars} } body { font-family: ${font.family}; }`}></style>
</head>
<body class="bg-background text-foreground antialiased font-sans">
  <slot />
</body>
</html>

files.src/styles/global.css:
@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  /* Ocean defaults — deploy pipeline overrides per-site via PUBLIC_COLORID */
  --primary: 217 91% 35%;
  --color-primary: 217 91% 35%;
  --secondary: 158 64% 42%;
  --accent: 15 92% 62%;
  --background: 210 40% 98%;
  --foreground: 222 47% 11%;
  --radius: 0.75rem;
}

@layer base {
  * {
    box-sizing: border-box;
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    margin: 0;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
}

@layer components {
  /* สไตล์สำหรับ slider ให้ดูสวยงามบนทุก browser */
  .range-slider {
    -webkit-appearance: none;
    appearance: none;
    height: 6px;
    border-radius: 9999px;
    outline: none;
    cursor: pointer;
  }

  .range-slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: hsl(var(--primary));
    cursor: pointer;
    border: 3px solid white;
    box-shadow: 0 2px 6px rgba(0,0,0,0.25);
    transition: transform 0.15s ease;
  }

  .range-slider::-webkit-slider-thumb:hover {
    transform: scale(1.15);
  }

  .range-slider::-moz-range-thumb {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: hsl(var(--primary));
    cursor: pointer;
    border: 3px solid white;
    box-shadow: 0 2px 6px rgba(0,0,0,0.25);
  }

  /* Animation สำหรับ modal */
  .modal-overlay {
    transition: opacity 0.2s ease;
  }

  .modal-content {
    transition: transform 0.25s ease, opacity 0.25s ease;
  }
}

@layer utilities {
  /* ซ่อน scrollbar แต่ยังคง scroll ได้ */
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }
  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
}

